const COURSE_WORDS=WORDS.length, COURSE_SETS=Math.ceil(COURSE_WORDS/20);
const app=document.getElementById('app');
let progress={known:[],scores:{},last:0},storageOK=true;
try{const s=JSON.parse(localStorage.getItem('mandarin20-v1'));if(s&&Array.isArray(s.known)&&s.scores&&typeof s.scores==='object')progress={...progress,...s};}catch(e){storageOK=false;}
progress.customSets=Array.isArray(progress.customSets)?progress.customSets.filter(s=>s&&typeof s.id==='string'&&typeof s.name==='string'&&Array.isArray(s.wordIds)).map(s=>({...s,wordIds:[...new Set(s.wordIds.filter(id=>Number.isInteger(id)&&id>=1&&id<=COURSE_WORDS))],scores:s.scores&&typeof s.scores==='object'?s.scores:{}})):[];
let setIndex=Math.min(COURSE_SETS-1,Math.max(0,Number(progress.last)||0)),cardIndex=0,revealed=false,filter='all',view='home',quiz=null;
const esc=s=>String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const setWords=i=>WORDS.slice(i*20,i*20+20);
const known=id=>progress.known.includes(id);
const learned=i=>setWords(i).filter(w=>known(w.id)).length;
const TEST_MODES={hanzi:'Hanzi',pinyin:'Pinyin',reverse:'Reverse Hanzi',typed:'Type English',pinyinTyped:'Type Pinyin'};
const num=i=>String(i+1).padStart(2,'0');
function save(){try{localStorage.setItem('mandarin20-v1',JSON.stringify(progress));}catch(e){storageOK=false;}}
function shuffle(a){const r=[...a];for(let i=r.length-1;i>0;i--){const j=Math.floor(Math.random()*(i+1));[r[i],r[j]]=[r[j],r[i]];}return r;}
function score(i,type){const s=progress.scores[i+'-'+type];return s===undefined?'Not tested':s+'/20';}
function nav(guide=false){document.getElementById('learnNav').classList.toggle('active',!guide);document.getElementById('guideNav').classList.toggle('active',guide);}
function home(){view='home';nav();const count=WORDS.filter(w=>known(w.id)).length;app.innerHTML=`<section class="hero"><div><div class="eyebrow">YOUR DAILY DOSE OF MANDARIN</div><h1>A little today.<br><em>A lot to discover.</em></h1><p class="sub">Make ${COURSE_WORDS} everyday Chinese words your own.<br>One focused set of twenty at a time.</p></div><div class="progress-card"><div class="progress-top"><span class="eyebrow" style="margin:0">YOUR WORD COLLECTION</span><span>✦</span></div><div style="margin-top:20px"><span class="big-stat">${count}</span><span class="small"> / ${COURSE_WORDS} words learned</span></div><div class="bar"><span style="width:${count*100/COURSE_WORDS}%"></span></div><div class="small">${COURSE_SETS-Array.from({length:COURSE_SETS},(_,i)=>learned(i)).filter(n=>n===20).length} sets left to explore · ${Math.round(count*100/COURSE_WORDS)}% of your journey</div></div></section><section class="continue"><div><div class="eyebrow">${count?'KEEP YOUR MOMENTUM':'START SMALL. BUILD CONFIDENCE.'}</div><h2>Set ${num(setIndex)} <span style="opacity:.5">/</span> Words ${setIndex*20+1}–${setIndex*20+20}</h2><div class="small" style="margin-top:8px">Learn the words, then put them to the test.</div></div><div class="characters" lang="zh-CN">${setWords(setIndex).slice(0,3).map(w=>w.hz).join(' ')}</div><button class="button lime" id="continue">${count?'Continue learning':'Start learning'} &nbsp; ↗</button></section><section class="learned-review"><div><div class="eyebrow">BRING IT ALL TOGETHER</div><h2>Test your learned words</h2><p class="small">${count} words across all sets · One shuffled test, every learned word.</p>${count?'':'<p class="small">Mark words as learned on their flashcards to unlock these tests.</p>'}</div><div class="review-actions"><button class="button primary" id="learnedHanzi" ${count?'':'disabled'}>Test Hanzi</button><button class="button" id="learnedPinyin" ${count?'':'disabled'}>Test Pinyin</button><button class="button" id="learnedReverse" ${count?'':'disabled'}>Reverse Hanzi</button><button class="button" id="learnedTyped" ${count?'':'disabled'}>Type English</button><button class="button" id="learnedPinyinTyped" ${count?'':'disabled'}>Type Pinyin</button></div></section><section class="infinite-home"><div><div class="eyebrow">MIX IT UP, KEEP GOING</div><h2>∞ Infinite Mode</h2><p class="small">All five test types. A fresh shuffle every round. End whenever you like.</p></div><div><label class="small" for="infinitePool">Choose your words</label><select id="infinitePool"><option value="all">All ${COURSE_WORDS} words</option><option value="learned">My learned words</option>${progress.customSets.map(set=>`<option value="${esc(set.id)}">${esc(set.name)}</option>`).join('')}</select><button class="button primary" id="startInfinite">Start Infinite Mode →</button><p class="status" id="infiniteStatus" role="status"></p></div></section><section class="custom-home"><div><h2>Your custom sets</h2><p class="small">${progress.customSets.length} sets · Pick words from across the list and test them together.</p></div><button class="button primary" id="manageCustom">Create & manage sets →</button></section><section><div class="section-head"><div><h2>Your learning path</h2><p class="small">${COURSE_SETS} sets · 20 words each · In the order of your word list</p></div><div class="filters" aria-label="Filter sets">${[['all','All sets'],['started','In progress'],['complete','Learned']].map(([v,l])=>`<button data-filter="${v}" class="${filter===v?'chosen':''}">${l}</button>`).join('')}</div></div><div class="sets" id="sets"></div></section><p class="notice">“Learned” is your flashcard self-assessment. All five test modes have separate scores.${storageOK?'':' Browser storage is unavailable; progress may not persist.'}</p>`;document.getElementById('startInfinite').onclick=startHomeInfinite;document.getElementById('learnedPinyinTyped').onclick=()=>startLearnedQuiz('pinyinTyped');document.getElementById('manageCustom').onclick=customSetsPage;document.getElementById('continue').onclick=()=>openSet(setIndex);document.getElementById('learnedHanzi').onclick=()=>startLearnedQuiz('hanzi');document.getElementById('learnedPinyin').onclick=()=>startLearnedQuiz('pinyin');document.getElementById('learnedReverse').onclick=()=>startLearnedQuiz('reverse');document.getElementById('learnedTyped').onclick=()=>startLearnedQuiz('typed');document.querySelectorAll('[data-filter]').forEach(b=>b.onclick=()=>{filter=b.dataset.filter;home();});renderSets();}
function renderSets(){const ids=Array.from({length:COURSE_SETS},(_,i)=>i).filter(i=>filter==='all'||(filter==='complete'?learned(i)===20:learned(i)>0&&learned(i)<20));document.getElementById('sets').innerHTML=ids.map(i=>`<button class="set-card" data-set="${i}"><div class="card-top"><span class="set-number">SET ${num(i)}</span><span class="pill">${learned(i)===20?'✓ Learned':learned(i)?'In progress':'20 words'}</span></div><div class="sample" lang="zh-CN">${setWords(i).slice(0,3).map(w=>w.hz).join(' ')}</div><div class="small">Words ${i*20+1}–${i*20+20}</div><div class="bar"><span style="width:${learned(i)*5}%"></span></div><div class="small">Hanzi ${score(i,'hanzi')} &nbsp;·&nbsp; Pinyin ${score(i,'pinyin')}<br>Reverse ${score(i,'reverse')} &nbsp;·&nbsp; Typed ${score(i,'typed')}<br>Type Pinyin ${score(i,'pinyinTyped')}</div><div class="card-bottom"><span class="small">${learned(i)} of 20 learned</span><span class="arrow">↗</span></div></button>`).join('')||'<p class="empty">No sets here yet. Start with a few flashcards.</p>';document.querySelectorAll('[data-set]').forEach(b=>b.onclick=()=>openSet(+b.dataset.set));}
function openSet(i){setIndex=i;progress.last=i;save();cardIndex=0;revealed=false;study();window.scrollTo(0,0);}
function study(){view='study';nav();app.innerHTML=`<button class="back" id="back">← All sets</button><div class="eyebrow">TWENTY WORDS, ONE STEP FORWARD</div><h1 style="font-size:36px">Set ${num(setIndex)} <span style="color:#929b86">/</span> Your next twenty</h1><p class="sub">Words ${setIndex*20+1}–${setIndex*20+20}. Meet them, remember them, make them yours.</p><div class="workspace"><aside class="side-panel"><div class="eyebrow">PRACTICE YOUR WAY</div><button class="mode selected" id="flashMode">▤ &nbsp; Flashcards<span>Learn at your own pace</span></button><button class="mode" id="hanziMode">字 &nbsp; Test Hanzi<span>Recognize the characters</span></button><button class="mode" id="pinyinMode">ā &nbsp; Test Pinyin<span>Recognize sounds & tones</span></button><button class="mode" id="reverseMode">字 → A &nbsp; Reverse Hanzi<span>Choose the English meaning</span></button><button class="mode" id="typedMode">⌨ &nbsp; Type English<span>Recall without options</span></button><button class="mode" id="pinyinTypedMode">⌨ &nbsp; Type Pinyin<span>Hanzi → numbered tones</span></button><button class="mode" id="infiniteSetMode">∞ &nbsp; Infinite Mode<span>Mix all five test types</span></button><div class="side-note">Your best full-set scores<br><strong>Hanzi: ${score(setIndex,'hanzi')}<br>Pinyin: ${score(setIndex,'pinyin')}<br>Reverse: ${score(setIndex,'reverse')}<br>Typed: ${score(setIndex,'typed')}<br>Type Pinyin: ${score(setIndex,'pinyinTyped')}</strong><br><br>Tip: say each word aloud before revealing its meaning.</div></aside><section><div id="card"></div><div class="section-head" style="margin-top:38px;margin-bottom:0"><h2>Inside this set</h2><span class="small" id="setLearnedCount">${learned(setIndex)} / 20 learned</span></div><input id="search" class="search" placeholder="Find a word, Pinyin or meaning…" aria-label="Search this set"><p class="small" style="margin-top:12px">Tick Learned beside any word to add it to your learned collection. Untick to undo.</p><div class="word-list" id="wordList"></div><p class="notice">Pinyin shows dictionary tones. 一 and 不 can change tone in speech; some words have other readings. See the study guide.</p></section></div>`;document.getElementById('back').onclick=home;document.getElementById('flashMode').onclick=()=>{cardIndex=0;revealed=false;renderCard();};document.getElementById('hanziMode').onclick=()=>startQuiz('hanzi');document.getElementById('pinyinMode').onclick=()=>startQuiz('pinyin');document.getElementById('reverseMode').onclick=()=>startQuiz('reverse');document.getElementById('typedMode').onclick=()=>startQuiz('typed');document.getElementById('pinyinTypedMode').onclick=()=>startQuiz('pinyinTyped');document.getElementById('infiniteSetMode').onclick=()=>startInfinite(setWords(setIndex),'set');document.getElementById('search').oninput=e=>renderWordList(e.target.value);renderCard();renderWordList('');}
function renderCard(){const w=setWords(setIndex)[cardIndex];document.getElementById('card').innerHTML=`<div class="study-card"><span class="counter">FLASHCARD ${cardIndex+1} / 20</span><div class="hanzi" lang="zh-CN">${w.hz}</div>${revealed?`<div class="pinyin" lang="zh-Latn">${w.py}</div><div class="meaning">${esc(w.en)}</div><button class="sound" style="margin-top:16px" id="listen" aria-label="Listen to pronunciation">♪</button>`:`<p class="small" style="margin:15px 0 20px">Do you know this word?</p><button class="button" id="reveal">Reveal Pinyin & meaning</button>`}</div><div class="card-tools"><div class="group"><button class="button ghost" id="prev" ${cardIndex===0?'disabled':''} aria-label="Previous word">←</button><button class="button ghost" id="next" ${cardIndex===19?'disabled':''} aria-label="Next word">→</button></div><button class="button ${known(w.id)?'ghost':'primary'}" id="mark">${known(w.id)?'✓ Learned · undo':'Mark as learned ✓'}</button>${cardIndex===19?'<button class="button" id="testNow">Test this set ↗</button>':''}</div><div class="status" id="audioStatus" role="status"></div>${revealed?examplesMarkup(w,'card-'):''}`;bindExamples();const r=document.getElementById('reveal');if(r)r.onclick=()=>{revealed=true;renderCard();};const l=document.getElementById('listen');if(l)l.onclick=()=>speak(w.hz);document.getElementById('prev').onclick=()=>move(-1);document.getElementById('next').onclick=()=>move(1);document.getElementById('mark').onclick=()=>setWordLearned(w.id,!known(w.id));const t=document.getElementById('testNow');if(t)t.onclick=()=>startQuiz('hanzi');}
function examplesMarkup(w,prefix){const examples=EXAMPLES[w.id]||[];const notes=USAGE_NOTES.filter(n=>n.words.includes(w.hz));return `<section class="examples-block" aria-label="Examples for ${esc(w.hz)}"><div class="example-heading"><h3>In everyday sentences</h3><span class="small">3 examples</span></div><ol class="examples-list">${examples.map((e,i)=>`<li><div class="example-line"><p class="example-hanzi" lang="zh-CN">${e.hz.split(w.hz).map(esc).join('<mark>'+esc(w.hz)+'</mark>')}</p><button class="sound" data-example-word="${w.id}" data-example-index="${i}" data-example-status="${prefix}audio" aria-label="Listen to example ${i+1} for ${esc(w.hz)}">♪</button></div><p class="example-pinyin" lang="zh-Latn">${esc(e.py)}</p><p class="example-english">${esc(e.en)}</p></li>`).join('')}</ol><div id="${prefix}audio" class="status" role="status"></div>${notes.map(n=>`<details class="usage-note"><summary>${esc(n.title)}</summary><p>${esc(n.body)}</p></details>`).join('')}<p class="notice">Pinyin uses dictionary tones, with syllables spaced for reading. Spoken 一, 不 and adjacent third tones may change; 儿 (er) can merge into the preceding syllable.</p></section>`;}
function bindExamples(){document.querySelectorAll('[data-example-word]').forEach(b=>b.onclick=()=>{const e=EXAMPLES[b.dataset.exampleWord][+b.dataset.exampleIndex];speak(e.hz,b.dataset.exampleStatus);});}
function move(d){cardIndex=Math.max(0,Math.min(19,cardIndex+d));revealed=false;renderCard();}
function renderWordList(q){const norm=s=>s.toLowerCase().normalize('NFD').replace(/[\u0300-\u036f]/g,'').replace(/\s/g,'');const rows=setWords(setIndex).filter(w=>norm(w.hz+w.py+w.en).includes(norm(q)));document.getElementById('wordList').innerHTML=rows.map(w=>`<div class="word-row study-word-row"><span class="small">${w.id}</span><span class="zh" lang="zh-CN">${w.hz}</span><span class="small">${w.py}</span><span class="translation">${esc(w.en)}</span><button class="sound" data-say="${w.id}" aria-label="Listen to ${w.hz}">♪</button><label class="learned-tick"><input type="checkbox" data-learned-word="${w.id}" aria-label="Mark ${w.hz} as learned" ${known(w.id)?'checked':''}> Learned</label></div><details class="word-examples"><summary>3 examples & usage for <span lang="zh-CN">${w.hz}</span></summary>${examplesMarkup(w,'list-'+w.id+'-')}</details>`).join('')||'<p class="empty">No matching words in this set.</p>';document.querySelectorAll('[data-say]').forEach(b=>b.onclick=()=>speak(WORDS[+b.dataset.say-1].hz));document.querySelectorAll('[data-learned-word]').forEach(input=>input.onchange=()=>setWordLearned(+input.dataset.learnedWord,input.checked));bindExamples();}
function speak(text,statusId='audioStatus'){const status=document.getElementById(statusId);if(!('speechSynthesis'in window)){if(status)status.textContent='Audio is not supported in this browser.';return;}const voices=speechSynthesis.getVoices(),voice=voices.find(v=>/^zh[-_]CN/i.test(v.lang))||voices.find(v=>/^zh/i.test(v.lang));if(!voice){if(status)status.textContent='No Chinese voice is available. Add a Mandarin voice in your device speech settings.';return;}speechSynthesis.cancel();const u=new SpeechSynthesisUtterance(text);u.lang='zh-CN';u.voice=voice;u.rate=.8;u.onerror=()=>{if(status)status.textContent='Audio could not play. Please try again.';};if(status)status.textContent='';speechSynthesis.speak(u);}
if('speechSynthesis'in window)speechSynthesis.getVoices();
function customSetById(id){return progress.customSets.find(s=>s.id===id);}
function createCustomSet(name){name=String(name).trim().slice(0,60);if(!name)return null;const set={id:'custom-'+Date.now().toString(36)+'-'+Math.random().toString(36).slice(2,10),name,wordIds:[],scores:{}};progress.customSets.push(set);save();return set;}
function toggleCustomWord(id,wordId){const set=customSetById(id);if(!set||!WORDS.some(w=>w.id===wordId))return;if(set.wordIds.includes(wordId))set.wordIds=set.wordIds.filter(n=>n!==wordId);else set.wordIds.push(wordId);set.scores={};save();}
function customSetsPage(){view='custom';nav();app.innerHTML=`<button class="back" id="customHome">← Your learning</button><div class="eyebrow">YOUR WORDS, YOUR WAY</div><h1>Custom sets</h1><p class="sub">Collect words from anywhere in the ${COURSE_WORDS}-word list. Make a set for tricky words, a topic, or your next review.</p><form id="createCustomForm" class="custom-create"><label for="customName">New set name</label><div class="custom-form-row"><input id="customName" class="search" maxlength="60" required placeholder="e.g. Words I keep mixing up"><button class="button primary" type="submit">Create set +</button></div></form><div class="sets">${progress.customSets.map(set=>`<button class="set-card" data-open-custom="${esc(set.id)}"><div class="card-top"><span class="set-number">CUSTOM SET</span><span class="pill">${set.wordIds.length} words</span></div><h2 style="font-size:22px;margin:20px 0;overflow-wrap:anywhere">${esc(set.name)}</h2><p class="small">${Object.entries(TEST_MODES).map(([type,label])=>`${label}: ${set.scores[type]===undefined?'—':set.scores[type]+'/'+set.wordIds.length}`).join('<br>')}</p><div class="card-bottom"><span class="small">Edit words & test</span><span class="arrow">↗</span></div></button>`).join('')||'<p class="empty">Create your first set, then add the words you want to practise.</p>'}</div><p class="notice">Custom sets are saved in this browser.${storageOK?'':' Browser storage is unavailable; your changes may not persist.'}</p>`;document.getElementById('customHome').onclick=home;document.getElementById('createCustomForm').onsubmit=e=>{e.preventDefault();const set=createCustomSet(document.getElementById('customName').value);if(set)editCustomSet(set.id);};document.querySelectorAll('[data-open-custom]').forEach(b=>b.onclick=()=>editCustomSet(b.dataset.openCustom));window.scrollTo(0,0);}
function editCustomSet(id){const set=customSetById(id);if(!set){customSetsPage();return;}view='custom-edit';nav();app.innerHTML=`<button class="back" id="customBack">← All custom sets</button><div class="eyebrow">CUSTOM SET</div><form id="renameCustomForm" class="custom-form-row"><input id="customRename" class="search custom-title" aria-label="Set name" maxlength="60" required value="${esc(set.name)}"><button class="button" type="submit">Rename</button></form><p id="customSaved" class="status" role="status"></p><section class="custom-test-panel"><div><h2 id="customCount">${set.wordIds.length} words selected</h2><p class="small">Every selected word appears once. Options can include other words from the full list.</p></div><div class="custom-test-actions" id="customTests"></div></section><div class="section-head"><h2>Choose your words</h2><select id="customFilter" aria-label="Filter words"><option value="all">All ${COURSE_WORDS} words</option><option value="selected">In this set</option><option value="learned">Marked as learned</option></select></div><input class="search" id="customSearch" aria-label="Find words for this set" placeholder="Search Hanzi, Pinyin or English…"><p class="small" style="margin-top:10px">Tick to add a word; untick to remove it. Changes save automatically. Changing words resets this set’s best scores.</p><div id="customWords" class="custom-word-list"></div><button id="deleteCustom" class="button ghost" style="margin-top:28px">Delete this set</button><div id="deleteConfirm"></div><p class="notice">${storageOK?'Saved locally in this browser.':'Browser storage is unavailable; changes may not persist.'}</p>`;document.getElementById('customBack').onclick=customSetsPage;document.getElementById('renameCustomForm').onsubmit=e=>{e.preventDefault();const name=document.getElementById('customRename').value.trim();if(name){set.name=name.slice(0,60);save();document.getElementById('customSaved').textContent=storageOK?'Name saved.':'Name changed, but browser storage is unavailable.';}};document.getElementById('customSearch').oninput=()=>renderCustomWords(id);document.getElementById('customFilter').onchange=()=>renderCustomWords(id);document.getElementById('deleteCustom').onclick=()=>{document.getElementById('deleteConfirm').innerHTML='<p class="notice">Delete this custom set and its scores? Your learned words and original sets will stay.</p><button class="button" id="confirmDeleteCustom">Delete set</button> <button class="button ghost" id="cancelDeleteCustom">Cancel</button>';document.getElementById('cancelDeleteCustom').onclick=()=>document.getElementById('deleteConfirm').innerHTML='';document.getElementById('confirmDeleteCustom').onclick=()=>{progress.customSets=progress.customSets.filter(s=>s.id!==id);save();customSetsPage();};};renderCustomTests(id);renderCustomWords(id);window.scrollTo(0,0);}
function renderCustomTests(id){const set=customSetById(id);document.getElementById('customCount').textContent=set.wordIds.length+' words selected';document.getElementById('customTests').innerHTML=Object.entries(TEST_MODES).map(([type,label])=>`<button class="button" data-custom-test="${type}" ${set.wordIds.length?'':'disabled'}>${label}<span class="small">${set.scores[type]===undefined?'Not tested':'Best: '+set.scores[type]+'/'+set.wordIds.length}</span></button>`).join('')+`<button class="button primary" id="customInfinite" ${set.wordIds.length?'':'disabled'}>∞ Infinite Mode</button>`;document.getElementById('customInfinite').onclick=()=>startInfinite(set.wordIds.map(id=>WORDS[id-1]),'custom',id);document.querySelectorAll('[data-custom-test]').forEach(b=>b.onclick=()=>startCustomQuiz(id,b.dataset.customTest));}
function customWordMatches(w,query){const norm=s=>String(s).toLowerCase().normalize('NFD').replace(/[\u0300-\u036f]/g,'').replace(/\s/g,'');return norm(w.hz+w.py+w.en).includes(norm(query));}
function renderCustomWords(id){const set=customSetById(id),query=document.getElementById('customSearch').value||'',filter=document.getElementById('customFilter').value||'all';const rows=WORDS.filter(w=>customWordMatches(w,query)&&(filter==='selected'?set.wordIds.includes(w.id):filter==='learned'?known(w.id):true));document.getElementById('customWords').innerHTML=rows.map(w=>`<label class="custom-word"><input type="checkbox" data-custom-word="${w.id}" ${set.wordIds.includes(w.id)?'checked':''}><span class="custom-word-hanzi" lang="zh-CN">${w.hz}</span><span class="small">${w.py}</span><span>${esc(w.en)}</span><span class="small">Set ${num(Math.floor((w.id-1)/20))}${known(w.id)?' · Learned':''}</span></label>`).join('')||'<p class="empty">No matching words. Try a different search or filter.</p>';document.querySelectorAll('[data-custom-word]').forEach(input=>input.onchange=()=>{toggleCustomWord(id,+input.dataset.customWord);renderCustomTests(id);if(filter==='selected')renderCustomWords(id);});}
function startCustomQuiz(id,type){const set=customSetById(id);if(!set||!set.wordIds.length)return;startQuiz(type,set.wordIds.map(id=>WORDS[id-1]),'custom',false,null,id);}
function returnFromQuiz(q){if(q.scope==='custom')editCustomSet(q.customId);else if(q.scope==='learned'||q.scope==='all')home();else study();}
function setWordLearned(id,value){if(!WORDS.some(w=>w.id===id))return;progress.known=progress.known.filter(n=>n!==id);if(value)progress.known.push(id);save();const count=document.getElementById('setLearnedCount');if(count)count.textContent=learned(setIndex)+' / 20 learned';document.querySelectorAll('[data-learned-word]').forEach(input=>{if(+input.dataset.learnedWord===id)input.checked=value;});if(view==='study'&&setWords(setIndex)[cardIndex].id===id){const mark=document.getElementById('mark');if(mark){mark.textContent=value?'✓ Learned · undo':'Mark as learned ✓';mark.className='button '+(value?'ghost':'primary');}}}
function addWordsToCustomSet(id,ids){const set=customSetById(id);if(!set)return 0;const valid=[...new Set(ids)].filter(id=>Number.isInteger(id)&&WORDS.some(w=>w.id===id));const added=valid.filter(id=>!set.wordIds.includes(id));if(added.length){set.wordIds.push(...added);set.scores={};save();}return added.length;}
function setAdderMarkup(prefix,label){return `<details class="set-adder"><summary>${esc(label)}</summary><form id="${prefix}form"><label for="${prefix}destination">Custom set</label><select id="${prefix}destination">${progress.customSets.map(set=>`<option value="${esc(set.id)}">${esc(set.name)}</option>`).join('')}<option value="__new__">+ Create a new set</option></select><div id="${prefix}new-wrap" ${progress.customSets.length?'hidden':''}><label for="${prefix}name">New set name</label><input id="${prefix}name" maxlength="60" placeholder="e.g. Needs practice" ${progress.customSets.length?'':'required'}></div><button type="submit" class="button primary">Add to set</button><p class="small">Words already in the set are kept once. Adding new words resets that custom set’s best scores.</p><p class="status" id="${prefix}status" role="status"></p></form></details>`;}
function bindSetAdder(prefix,getIds){const form=document.getElementById(prefix+'form');if(!form)return;const dest=document.getElementById(prefix+'destination'),name=document.getElementById(prefix+'name'),wrap=document.getElementById(prefix+'new-wrap'),status=document.getElementById(prefix+'status');dest.onchange=()=>{const fresh=dest.value==='__new__';wrap.hidden=!fresh;name.required=fresh;};form.onsubmit=e=>{e.preventDefault();const ids=[...new Set(getIds())].filter(id=>Number.isInteger(id)&&WORDS.some(w=>w.id===id));if(!ids.length){status.textContent='Select at least one word first.';return;}let set=customSetById(dest.value);if(dest.value==='__new__'){set=createCustomSet(name.value);if(!set){status.textContent='Enter a name for your new set.';name.focus();return;}dest.innerHTML=progress.customSets.map(s=>`<option value="${esc(s.id)}">${esc(s.name)}</option>`).join('')+'<option value="__new__">+ Create a new set</option>';dest.value=set.id;wrap.hidden=true;name.required=false;name.value='';}if(!set){status.textContent='Choose an existing set or create a new one.';return;}const added=addWordsToCustomSet(set.id,ids);status.textContent=added?`Added ${added} ${added===1?'word':'words'} to “${set.name}”.`:`These words are already in “${set.name}”.`;if(!storageOK)status.textContent+=' Browser storage is unavailable; this may not persist.';};}
function enableOptionMeanings(){const q=quiz;if(!q?.answered)return;document.querySelectorAll('[data-answer]').forEach((button,i)=>{const w=q.choices[i];if(!w)return;button.classList.add('has-meaning');button.title=w.hz+' · '+w.py+' · '+w.en;const tipId='option-meaning-'+i;button.setAttribute('aria-describedby',tipId);button.insertAdjacentHTML('beforeend',`<span class="option-meaning" id="${tipId}" role="tooltip"><span lang="zh-CN">${esc(w.hz)}</span> · ${esc(w.py)}<br>${esc(w.en)}</span>`);});const help=document.getElementById('optionHelp');if(help)help.textContent='Hover over or focus an option to see its meaning. Tap an option to show its meaning and hear it.';}
function pinyinCharacters(value){const tones={'\u0304':1,'\u0301':2,'\u030c':3,'\u0300':4};const out=[];for(const char of String(value).toLowerCase().replace(/u:/g,'ü').replace(/v/g,'ü').normalize('NFD')){if(/[\s'’\-]/.test(char))continue;if(tones[char]){const last=out[out.length-1];if(!last||last.tone)return null;last.tone=tones[char];}else if(char==='\u0308'){const last=out[out.length-1];if(!last||last.char!=='u')return null;last.char='ü';}else if(/[a-z0-5]/.test(char))out.push({char,tone:0});else return null;}return out;}
function pinyinSyllables(py){return py.trim().split(/\s+/).map(s=>{const chars=pinyinCharacters(s);return {base:chars.map(x=>x.char).join(''),tone:chars.find(x=>x.tone)?.tone||5};});}
function numberedPinyin(w){return pinyinSyllables(w.py).map(s=>s.base+(s.tone===5?'':s.tone)).join(' ');}
function matchesPinyin(w,value,strict=false){let input=pinyinCharacters(value);if(!input||!input.length)return false;let pos=0;for(const syllable of pinyinSyllables(w.py)){let tone=0;for(const char of syllable.base){const next=input[pos++];if(!next||next.char!==char)return false;if(next.tone){if(tone&&tone!==next.tone)return false;tone=next.tone;}}if(pos<input.length&&/^[0-5]$/.test(input[pos].char)){const digit=Number(input[pos++].char)||5;if(tone&&tone!==digit)return false;tone=digit;}if(tone&&tone!==syllable.tone)return false;if(strict&&!tone&&syllable.tone!==5)return false;}return pos===input.length;}
function nextMixedType(q){if(!q.modeBag.length)q.modeBag=shuffle(Object.keys(TEST_MODES));return q.modeBag.pop();}
function startInfinite(words=WORDS,scope='all',customId=null){if(!words.length)return;quiz={infinite:true,type:'hanzi',scope,customId,customName:customId?customSetById(customId)?.name:'',pool:[...words],words:shuffle(words),at:0,correct:0,attempted:0,missed:[],modeBag:[],answered:false,full:false,retry:false};quiz.type=nextMixedType(quiz);view='quiz';renderQuiz();window.scrollTo(0,0);}
function startHomeInfinite(){const value=document.getElementById('infinitePool').value;const set=customSetById(value);const words=value==='learned'?WORDS.filter(w=>known(w.id)):set?set.wordIds.map(id=>WORDS[id-1]):WORDS;if(!words.length){document.getElementById('infiniteStatus').textContent='Add words to this collection before starting.';return;}startInfinite(words,set?'custom':value==='learned'?'learned':'all',set?.id||null);}
function advanceQuiz(){const q=quiz;q.at++;if(q.infinite){if(q.at===q.words.length){const last=q.words[q.at-1];q.words=shuffle(q.pool);if(q.words.length>1&&q.words[0].id===last.id)[q.words[0],q.words[1]]=[q.words[1],q.words[0]];q.at=0;}q.type=nextMixedType(q);renderQuiz();window.scrollTo(0,0);}else if(q.at===q.words.length)finish();else renderQuiz();}
function finishInfinite(){const q=quiz;view='results';app.innerHTML=`<div class="question"><button class="back" id="infiniteBack">← Your learning</button><div class="result"><div class="eyebrow">INFINITE MODE · SESSION COMPLETE</div><h1 style="font-size:36px">Keep what you learned.</h1><div class="result-number">${q.correct}<span style="font-size:28px"> / ${q.attempted}</span></div><p class="sub" style="margin:0 auto 24px">${q.attempted?Math.round(100*q.correct/q.attempted)+'% accuracy across mixed test types.':'No answers submitted this session.'} Your regular test scores stay separate.</p><div class="review-actions" style="margin:auto;justify-content:center"><button class="button primary" id="infiniteAgain">Start another session</button>${q.missed.length?'<button class="button" id="infiniteMissed">Practise missed words</button>':''}</div></div>${q.missed.length?`<h2 style="margin-top:30px">Words to revisit</h2><p class="small">Words missed at least once this session. Select any to save.</p>${setAdderMarkup('infinite-add-','Add selected words to a custom set')}<div class="word-list">${q.missed.map(w=>`<div class="word-row"><input type="checkbox" data-infinite-missed="${w.id}" checked aria-label="Select ${w.hz}"><span class="zh">${w.hz}</span><span>${w.py}</span><span class="translation">${esc(w.en)}</span></div>`).join('')}</div>`:''}</div>`;document.getElementById('infiniteBack').onclick=()=>returnFromQuiz(q);document.getElementById('infiniteAgain').onclick=()=>startInfinite(q.pool,q.scope,q.customId);if(q.missed.length){document.getElementById('infiniteMissed').onclick=()=>startInfinite(q.missed,q.scope,q.customId);bindSetAdder('infinite-add-',()=>Array.from(document.querySelectorAll('[data-infinite-missed]')).filter(x=>x.checked).map(x=>+x.dataset.infiniteMissed));}window.scrollTo(0,0);}
function startLearnedQuiz(type){const words=WORDS.filter(w=>known(w.id));if(!words.length)return;startQuiz(type,words,'learned');}
function startQuiz(type,words,scope='set',retry=false,pool=null,customId=null){const selected=words||setWords(setIndex);if(!selected.length)return;quiz={type,scope,customId,customName:customId?customSetById(customId)?.name:'',pool:pool||[...selected],words:shuffle(selected),at:0,correct:0,missed:[],answered:false,full:scope==='set'&&!words,retry:retry||(scope==='set'&&!!words)};view='quiz';renderQuiz();window.scrollTo(0,0);}
function quizLabel(q){return q.scope==='all'?`ALL ${COURSE_WORDS} WORDS`:q.scope==='custom'?'CUSTOM · '+esc(q.customName||'Custom set'):q.scope==='learned'?'ALL LEARNED WORDS':'SET '+num(setIndex);}
function replayQuiz(q,type=q.type){if(q.scope==='custom'){startQuiz(type,q.pool,'custom',false,null,q.customId);return;}if(q.scope==='learned')startQuiz(type,q.pool,'learned');else startQuiz(type);}
function normalizeEnglish(value){return String(value).toLowerCase().normalize('NFKC').replace(/[’']/g,'').replace(/[^a-z0-9\s-]/g,' ').replace(/-/g,' ').replace(/\s+/g,' ').trim().replace(/^(?:to |a |an |the )+/,'');}
const ENGLISH_ALIASES={1:['possessive particle','possession','possessive','of'],4:['be','is','am','are'],5:['completion particle','change of state particle'],6:['no'],9:['we','us'],14:['know how','know how to'],15:['question particle','yes no question'],16:['want','would like','intend to'],20:['would like','would like to','miss','think'],25:['suggestion particle'],30:['be able to','able to'],32:['have not','has not','did not'],38:['ah'],49:['complement particle'],52:['ongoing state particle','aspect particle'],57:['be allowed to','allowed to'],59:['follow up question particle'],62:['dont'],85:['thanks'],96:['enjoy'],102:['yes','thats right'],128:['mm','hmm','yes'],167:['mom','mother','mum','mommy','mummy'],190:['father','dad','daddy'],192:['apologies','apologize','apologise'],199:['dont','do not'],200:['sorry','excuse me'],224:['mom','mother','mum'],225:['adverbial marker','adverbial particle'],230:['you'],237:['particle','persuasion particle'],243:['etc','et cetera','and so on','wait'],248:['physician'],267:['and','with'],274:['particle','sentence final particle'],288:['dad'],293:['usa','us','america','united states of america'],315:['hello','hey'],321:['son'],332:['particle'],337:['ms','madam','lady'],342:['not at all','fundamentally'],360:['how many','how much'],375:['week'],378:['father','daddy'],379:['two','two people'],381:['cant','cannot','can not'],382:['damn','fuck','fucking'],390:['thanks','thank you'],401:['never','always','ever'],430:['damn','dammit'],438:['well','properly','carefully'],444:['jerk','bastard'],445:['cup','glass'],458:['movie','film'],463:['regardless of','no matter'],473:['outcome'],480:['stay','stunned'],488:['ordinal prefix'],492:['officer','commanding officer'],493:['member','employee'],496:['attorney'],497:['oh']};
function englishAnswers(w){const raw=w.en.replace(/\([^)]*\)/g,'').split(/[;/]/);return [...new Set([w.en,...raw,...(ENGLISH_ALIASES[w.id]||[])].map(normalizeEnglish).filter(Boolean))];}
function matchesEnglish(w,value){const input=normalizeEnglish(value);return !!input&&englishAnswers(w).includes(input);}
function choicesFor(w,type){const key=type==='hanzi'?'hz':type==='pinyin'?'py':'en',chosen=[w];for(const x of shuffle([...setWords(setIndex),...WORDS])){if(chosen.some(c=>c[key]===x[key]))continue;if(key==='en'&&chosen.some(c=>englishAnswers(c).some(a=>englishAnswers(x).includes(a))))continue;chosen.push(x);if(chosen.length===4)break;}return shuffle(chosen);}
function renderQuiz(){
 const q=quiz,w=q.words[q.at],hanzi=q.type==='hanzi',pinyinTyped=q.type==='pinyinTyped',typed=q.type==='typed'||pinyinTyped,reverse=q.type==='reverse'||typed;
 q.answered=false;q.override=false;q.choices=typed?[]:choicesFor(w,q.type);
 app.innerHTML=`<div class="question"><button class="back" id="exitQuiz">${q.infinite?'End session & see results':'← Leave test'}</button><div class="quiz-top"><span class="eyebrow" style="margin:0">${quizLabel(q)} · ${TEST_MODES[q.type].toUpperCase()} ${q.infinite?'· ∞ INFINITE':q.retry?'REVIEW':'TEST'}</span><span class="small">${q.infinite?'Question '+(q.attempted+1):q.at+1+' / '+q.words.length}</span></div><div class="bar"><span style="width:${q.at/q.words.length*100}%"></span></div><div class="quiz-prompt"><p class="small">${hanzi?'Choose the Hanzi for this meaning.':pinyinTyped?'Type the Pinyin for this Hanzi.':typed?'Type one English meaning for this word.':reverse?'Choose the English meaning for this Hanzi.':'Choose the Pinyin, including the correct tones.'}</p>${hanzi?`<h2 style="margin-top:32px;font-size:30px">${esc(w.en)}</h2><div class="hint"><button class="button ghost" id="toggleHint" aria-expanded="false" aria-controls="pinyinHint">Show Pinyin hint</button><p id="pinyinHint" class="pinyin" lang="zh-Latn" hidden>${w.py}</p></div>`:`<button class="hanzi word-pronounce" id="promptWord" lang="zh-CN" aria-label="Listen to ${w.hz}">${w.hz}</button>${reverse?'':`<p class="small">${esc(w.en)}</p>`}`}<div class="test-audio"><button class="button" id="quizListen" aria-label="Play word pronunciation">♪ &nbsp; Listen to word</button><div class="status" id="audioStatus" role="status"></div></div></div>${typed?`<form id="typedForm" class="typed-form"><label for="typedAnswer">${pinyinTyped?'Pinyin':'English meaning'}</label><input id="typedAnswer" class="search" placeholder="${pinyinTyped?'e.g. shi4 or mei2you':'Type one meaning…'}" autocomplete="off" autocapitalize="off" spellcheck="false" required maxlength="200" aria-describedby="typedHelp"><p class="small" id="typedHelp">${pinyinTyped?'Use tone numbers or marks, with or without spaces. Neutral tone: no number, 0 or 5. Use ü, v or u:. Omitted tones are accepted unless strict mode is on; wrong tones are never accepted.':'One listed meaning is enough. Common variants are accepted; you can review and self-correct after checking.'}</p>${pinyinTyped?`<label class="strict-tones"><input id="strictPinyin" type="checkbox" ${progress.pinyinStrict?'checked':''}> Require every tone (neutral tones can stay unmarked)</label>`:''}<button class="button primary" id="checkTyped" type="submit">Check answer →</button></form>`:`<div class="options ${reverse?'english-options':''}">${q.choices.map((c,i)=>`<button class="option" data-answer="${i}" lang="${hanzi?'zh-CN':reverse?'en':'zh-Latn'}">${esc(hanzi?c.hz:reverse?c.en:c.py)}</button>`).join('')}</div><p class="small option-help" id="optionHelp">Select an answer to hear its pronunciation. After answering, tap any option to listen again.</p>`}<div id="feedback"></div><div class="quiz-bottom"><span class="small" id="quizTally">${q.correct} correct so far</span><button class="button ghost" id="skip">I don’t know</button></div><p class="notice">${q.infinite?'Infinite Mode keeps reshuffling this collection and mixes all five test types. End the session any time for a summary.':q.retry?'Retrying missed words. This does not replace your full-set score.':q.scope==='custom'?`All ${q.words.length} custom-set words appear once. This set has its own scores.`:q.scope==='learned'?`All ${q.words.length} learned words appear once, across your sets. Set scores stay separate.`:'Each of the 20 words appears once. Your best score is saved when you finish.'}</p></div>`;
 document.getElementById('exitQuiz').onclick=()=>q.infinite?finishInfinite():returnFromQuiz(q);
 document.getElementById('quizListen').onclick=()=>speak(w.hz);
 if(!hanzi)document.getElementById('promptWord').onclick=()=>speak(w.hz);
 if(hanzi)document.getElementById('toggleHint').onclick=()=>{const content=document.getElementById('pinyinHint'),hint=document.getElementById('toggleHint');content.hidden=!content.hidden;hint.setAttribute('aria-expanded',String(!content.hidden));hint.textContent=content.hidden?'Show Pinyin hint':'Hide Pinyin hint';};
 document.querySelectorAll('[data-answer]').forEach(b=>b.onclick=()=>chooseAnswer(+b.dataset.answer));
 if(pinyinTyped)document.getElementById('strictPinyin').onchange=e=>{progress.pinyinStrict=e.target.checked;save();};
 if(typed){document.getElementById('typedForm').onsubmit=e=>{e.preventDefault();const value=document.getElementById('typedAnswer').value.trim();if(value)answerTyped(value);};document.getElementById('typedAnswer').focus();}
 document.getElementById('skip').onclick=()=>typed?answerTyped('',true):answer(-1);
}
function chooseAnswer(index){const choice=quiz.choices[index];if(!choice)return;speak(choice.hz);if(!quiz.answered)answer(index);else document.querySelectorAll('[data-answer]').forEach((b,i)=>b.classList.toggle('show-meaning',i===index));}
function answer(index){if(quiz.answered)return;const chosen=index>=0?quiz.choices[index]:null;completeAnswer(!!chosen&&chosen.id===quiz.words[quiz.at].id,chosen,'',index<0);}
function answerTyped(value,skipped=false){if(quiz.answered)return;completeAnswer(!skipped&&(quiz.type==='pinyinTyped'?matchesPinyin(quiz.words[quiz.at],value,!!progress.pinyinStrict):matchesEnglish(quiz.words[quiz.at],value)),null,value,skipped);}
function wordFeedback(w,label){return `<div class="word-feedback"><p class="small">${label}</p><button class="word-pronounce feedback-word" data-feedback-word="${w.id}" lang="zh-CN" aria-label="Listen to ${w.hz}">${w.hz} ♪</button><span class="feedback-pinyin">${esc(w.py)}</span><p>${esc(w.en)}</p></div>`;}
function completeAnswer(correct,chosen,typedValue,skipped){
 const q=quiz;if(q.answered)return;q.answered=true;q.lastCorrect=correct;enableOptionMeanings();const w=q.words[q.at];if(q.infinite)q.attempted++;if(correct)q.correct++;else if(!q.infinite||!q.missed.some(x=>x.id===w.id))q.missed.push(w);
 document.querySelectorAll('[data-answer]').forEach((b,i)=>{if(q.choices[i].id===w.id)b.classList.add('correct');else if(chosen&&q.choices[i].id===chosen.id)b.classList.add('wrong');});
 if(q.type==='typed'||q.type==='pinyinTyped'){document.getElementById('typedAnswer').disabled=true;document.getElementById('checkTyped').disabled=true;}
 document.getElementById('skip').disabled=true;document.getElementById('quizTally').textContent=q.correct+' correct so far';
 const related=q.type==='typed'&&!correct&&!chosen&&typedValue?WORDS.filter(x=>x.id!==w.id&&matchesEnglish(x,typedValue)).slice(0,3):[];
 document.getElementById('feedback').innerHTML=`<div class="feedback"><strong id="answerStatus" tabindex="-1" role="status">${correct?'Nicely done.':skipped?'A word to revisit.':'Not quite. Compare the meanings below.'}</strong>${typedValue?`<p class="typed-response">Your answer: <strong>${esc(typedValue)}</strong></p>`:''}${q.type==='pinyinTyped'?`<p class="numbered-answer">Numbered Pinyin: <strong>${esc(numberedPinyin(w))}</strong></p>`:''}<div class="answer-comparison">${wordFeedback(w,'Correct word')}${!correct&&chosen?wordFeedback(chosen,'You selected — this word means'):''}</div>${related.length?`<div class="typed-related"><p class="small">Your English answer also matches these entries:</p>${related.map(x=>wordFeedback(x,'Related word')).join('')}</div>`:''}${!correct&&q.type==='typed'&&!skipped?'<p class="small" style="margin-top:14px">Another valid translation? Compare it with the meaning above before self-correcting.</p><button class="button ghost" id="acceptTyped" style="margin-top:10px">Count my answer as correct</button>':''}<button class="button primary" id="nextQuestion" style="margin-top:16px">${!q.infinite&&q.at===q.words.length-1?'See results':'Next word →'}</button></div>${setAdderMarkup('answer-add-','Add this word to a custom set')}${examplesMarkup(w,'quiz-example-')}`;
 bindSetAdder('answer-add-',()=>[w.id]);bindExamples();document.querySelectorAll('[data-feedback-word]').forEach(b=>b.onclick=()=>speak(WORDS[+b.dataset.feedbackWord-1].hz));
 if(!correct&&q.type==='typed'&&!skipped)document.getElementById('acceptTyped').onclick=acceptTypedAnswer;
 document.getElementById('nextQuestion').onclick=advanceQuiz;document.getElementById('answerStatus').focus();
}
function acceptTypedAnswer(){const q=quiz;if(!q.answered||q.lastCorrect||q.override||q.type!=='typed')return;q.override=true;q.lastCorrect=true;q.correct++;const id=q.words[q.at].id;if(!q.infinite)q.missed=q.missed.filter(w=>w.id!==id);document.getElementById('answerStatus').textContent='Counted as correct — self-reviewed.';document.getElementById('acceptTyped').disabled=true;document.getElementById('quizTally').textContent=q.correct+' correct so far';}
function finish(){if(quiz.infinite){finishInfinite();return;}view='results';const q=quiz;if(q.scope==='custom'&&!q.retry){const set=customSetById(q.customId);if(set&&set.wordIds.length===q.pool.length&&q.pool.every(w=>set.wordIds.includes(w.id))){set.scores[q.type]=Math.max(set.scores[q.type]||0,q.correct);save();}}if(q.full){const k=setIndex+'-'+q.type;progress.scores[k]=Math.max(progress.scores[k]||0,q.correct);save();}app.innerHTML=`<div class="question"><button class="back" id="backSet">← ${q.scope==='custom'?'Back to custom set':q.scope==='learned'?'Your learning':'Back to set'}</button><div class="result"><div class="eyebrow">${quizLabel(q)} · ${TEST_MODES[q.type].toUpperCase()} ${q.retry?'REVIEW':'TEST'} COMPLETE</div><h1 style="font-size:36px">${q.correct===q.words.length?'Another step forward.':'Every attempt is progress.'}</h1><div class="result-number">${q.correct}<span style="font-size:28px;color:#8c9787"> / ${q.words.length}</span></div><p class="sub" style="margin:0 auto 25px">${q.missed.length?`${q.missed.length} words could use another look. A quick retry helps them stick.`:'You answered every word in this round. Keep the momentum going.'}</p><div style="display:flex;gap:10px;justify-content:center;flex-wrap:wrap">${q.missed.length?'<button class="button primary" id="retry">Retry missed words</button>':''}${Object.entries(TEST_MODES).filter(([type])=>type!==q.type).map(([type,label])=>`<button class="button" data-replay-mode="${type}">${label}</button>`).join('')}<button class="button ghost" id="again">Retake full test</button>${q.scope==='set'&&setIndex+1<COURSE_SETS?'<button class="button ghost" id="nextSet">Next set →</button>':''}</div></div>${q.missed.length?`<h2 style="margin-top:30px">Words to revisit</h2><p class="small" style="margin-top:10px">Select the words to add to a custom set. All missed words are selected to start.</p>${setAdderMarkup('revisit-add-','Add selected words to a custom set')}<div class="word-list">${q.missed.map(w=>`<div class="word-row"><label class="revisit-tick"><input type="checkbox" data-revisit-word="${w.id}" checked aria-label="Select ${w.hz} for custom set"></label><span class="zh">${w.hz}</span><span>${w.py}</span><span class="translation">${esc(w.en)}</span></div>`).join('')}</div>`:''}</div>`;if(q.missed.length)bindSetAdder('revisit-add-',()=>Array.from(document.querySelectorAll('[data-revisit-word]')).filter(input=>input.checked).map(input=>+input.dataset.revisitWord));document.getElementById('backSet').onclick=()=>returnFromQuiz(q);const retry=document.getElementById('retry');if(retry)retry.onclick=()=>startQuiz(q.type,q.missed,q.scope,true,q.pool,q.customId);document.querySelectorAll('[data-replay-mode]').forEach(b=>b.onclick=()=>replayQuiz(q,b.dataset.replayMode));document.getElementById('again').onclick=()=>replayQuiz(q);const ns=document.getElementById('nextSet');if(ns)ns.onclick=()=>openSet(setIndex+1);}
function guide(){view='guide';nav(true);app.innerHTML=`<div class="guide"><div class="eyebrow">A SIMPLE ROUTINE</div><h1>Small sets.<br>Lasting connections.</h1><p class="sub">Meet the meaning, recognize the characters, remember the sound.</p><article><h2>01 · Learn twenty words</h2><p>Open a set and try to recall each flashcard before revealing its Pinyin and English meaning. Say the word aloud. Each revealed card includes three example sentences with Pinyin and English, plus relevant usage comparisons. You can also open these from any word in the set list. Use the music button to hear an example. Mark a word as learned when you feel comfortable with it, or tick several words while scrolling through “Inside this set.” Untick to undo.</p></article><article><h2>02 · Separate the skills</h2><p><strong>Hanzi test:</strong> see an English meaning, then select the Chinese characters. The Pinyin hint starts hidden for every word; use “Show Pinyin hint” to reveal it and toggle it off again. <strong>Pinyin test:</strong> see the characters and meaning, then select the correct pronunciation, including tones. <strong>Reverse Hanzi:</strong> see the characters and choose the English meaning. <strong>Type Pinyin:</strong> see Hanzi and enter numbered Pinyin (shi4, mei2you) or tone marks. Spaces are optional; omitted tones are accepted unless “Require every tone” is enabled. Neutral tone may be unmarked, 0 or 5. Use dictionary tones, and ü, v or u: for the ü vowel. <strong>Type English:</strong> see the characters and type one meaning without options. Matching ignores capitalization, punctuation and an initial “to,” “a,” or “the,” and accepts listed meanings plus common variants. If a valid translation is missed, compare the revealed answer and use “Count my answer as correct.” Click a word to hear it; selecting an option also plays its pronunciation. After answering, review the correct word’s examples and the meaning of a mistaken choice. Hover over or focus the other options to see their meanings, or tap them on a touch screen. Use “Add this word to a custom set” to save the tested word without leaving the test. On “Words to revisit,” select any missed words and add them to an existing or new custom set.</p><p>Each full test covers all 20 words in a shuffled order. Review feedback after each answer and retry your missed words at the end. Scores for all five modes are saved independently, including any self-corrected typed answers. On your learning page, “Test your learned words” combines every word you have marked as learned across all ${COURSE_SETS} sets. Choose any of the five modes; each learned word appears once. These mixed tests do not change individual set scores. Use “Create & manage sets” on your learning page to name a custom set and tick words from anywhere in the list. All five test modes work with custom sets, with separate best scores. Editing a set’s words resets its scores; renaming it keeps them.</p></article><article><h2>03 · Hear the tones</h2><p>Infinite Mode keeps cycling through your chosen words and mixes all five test types, using each type once per shuffled group of five questions. Choose all ${COURSE_WORDS} words, your learned words, an original set or a custom set. End the session at any point for accuracy and a list of words missed at least once. Infinite sessions do not replace regular test scores.</p><p>Mandarin has four main tones: <strong>ā</strong> high and level, <strong>á</strong> rising, <strong>ǎ</strong> low or dipping, and <strong>à</strong> falling. A syllable without a tone mark is neutral. The two dots in <strong>ü</strong> mark a different vowel from <strong>u</strong>.</p><p>The listening button uses an available Chinese voice on your device. Voice availability and pronunciation quality depend on your browser and installed voices.</p></article><article><h2>A note on readings</h2><p>This app gives common readings for the listed meanings, not every possible reading. For example, 还 is <strong>hái</strong> (“still”) but <strong>huán</strong> means “return”; 得 can be <strong>de</strong>, <strong>dé</strong> or <strong>děi</strong>; 长 can be <strong>cháng</strong> (“long”) or <strong>zhǎng</strong> (“grow”). 地 is <strong>de</strong> as a particle and <strong>dì</strong> for “ground”.</p><p>Dictionary tones are shown: 一 is <strong>yī</strong> and 不 is <strong>bù</strong>. In connected speech, their tones can change. Adjacent third tones also change in pronunciation. Neutral tones and interjections can vary by speaker and context.</p></article><article><h2>Your list, preserved</h2><p>All ${COURSE_WORDS} entries appear in the uploaded order, grouped into ${COURSE_SETS} sets of 20. The original 500-word list credits the SUBTLEX-CH subtitle corpus (Cai & Brysbaert, 2010). Entries 501–1500 follow your supplied expansion. Cards use a common reading with a matching English meaning; some characters have other readings in other contexts. Subtitle vocabulary includes some insults and profanity; these are labelled in their meanings.</p><p>Progress is saved locally in this browser. It does not sync across devices, and clearing browser data will remove it.</p></article><article><h2>Words that look similar in English</h2><p>Usage notes compare common meanings and contexts, rather than treating translations as exact equivalents. Open a word’s examples to see the notes that apply to it.</p><p>Further reading: <a href="https://www.thepurelanguage.com/chinese-grammar/xiang-yao-xuyao" target="_blank" rel="noopener noreferrer">想 / 要 / 需要</a> and <a href="https://www.thepurelanguage.com/chinese-grammar/hui-neng-keyi" target="_blank" rel="noopener noreferrer">会 / 能 / 可以</a>. The app’s example sentences were written for this course.</p></article><button class="button primary" id="returnHome">Back to your learning →</button></div>`;document.getElementById('returnHome').onclick=home;window.scrollTo(0,0);}
document.querySelector('.brand').onclick=e=>{e.preventDefault();home();};document.getElementById('learnNav').onclick=home;document.getElementById('guideNav').onclick=guide;home();

document.getElementById('courseSize').textContent=COURSE_WORDS+' words. '+COURSE_SETS+' small steps.';
